package nl.worldmorph.npc; import java.util.*; public final class NpcProfile { private final UUID id; private final String name; private int age=20,money,ambition,loyalty=50; private boolean alive=true; private String job="UNEMPLOYED"; private UUID familyId,settlementId,kingdomId; private final List<Memory> memories=new ArrayList<>(); private final Map<UUID,Integer> relationships=new HashMap<>(); private NpcPersonality personality=NpcPersonality.KIND; public NpcProfile(UUID id,String name){this.id=id;this.name=name;} public UUID id(){return id;} public String name(){return name;} public int age(){return age;} public int money(){return money;} public int ambition(){return ambition;} public int loyalty(){return loyalty;} public boolean alive(){return alive;} public String job(){return job;} public UUID familyId(){return familyId;} public UUID settlementId(){return settlementId;} public UUID kingdomId(){return kingdomId;} public NpcPersonality personality(){return personality;} public List<Memory> memories(){return List.copyOf(memories);} public void addMemory(String t,UUID target,long tick,int importance){memories.add(new Memory(t,target,tick,importance));if(memories.size()>100)memories.removeFirst();} public void changeLoyalty(int n){loyalty=Math.max(0,Math.min(100,loyalty+n));} public void changeMoney(int n){money=Math.max(0,money+n);} public void setJob(String x){job=x;} public void setKingdom(UUID x){kingdomId=x;} public void setSettlement(UUID x){settlementId=x;} public void setFamily(UUID x){familyId=x;} public void setAmbition(int x){ambition=Math.max(0,Math.min(100,x));} public void ageOne(){age++;} public void die(){alive=false;} public record Memory(String type,UUID target,long tick,int importance){} }